out2=[[2]*13 for _ in range(13)]
panels=[(1,1,9,[[0,1,0],[0,0,0],[1,0,1]]),
        (1,7,6,[[1,0,0],[1,0,0],[0,1,1]]),
        (7,1,3,[[0,1,0],[1,0,0],[1,0,1]]),
        (7,7,4,[[0,0,0],[1,0,1],[1,0,1]])]
for r,c,col,inner in panels:
    for dr in range(5):
        for dc in range(5):
            out2[r+dr][c+dc]=col if dr in (0,4) or dc in (0,4) else (col if inner[dr-1][dc-1] else 2)
print('\n'.join(' '.join(map(str,row)) for row in out2))
